<section class="page-head"><div><p class="eyebrow">OYUN KATEGORİSİ</p><h1><?= e($category['name']) ?></h1><?php if(!empty($category['description'])): ?><p><?= e($category['description']) ?></p><?php endif; ?><p><?= count($products) ?> ürün listeleniyor.</p></div></section><form class="category-toolbar" method="get"><label>Sıralama<select name="sort"><option value="default" <?= ($categorySort??'default')==='default'?'selected':'' ?>>Önerilen</option><option value="newest" <?= ($categorySort??'')==='newest'?'selected':'' ?>>En yeni</option><option value="price_asc" <?= ($categorySort??'')==='price_asc'?'selected':'' ?>>Fiyat: artan</option><option value="price_desc" <?= ($categorySort??'')==='price_desc'?'selected':'' ?>>Fiyat: azalan</option><option value="name_asc" <?= ($categorySort??'')==='name_asc'?'selected':'' ?>>İsim: A–Z</option></select></label><label>En düşük fiyat<input type="number" name="min_price" min="0" step="0.01" value="<?= e($minPrice??'') ?>" placeholder="₺"></label><label>En yüksek fiyat<input type="number" name="max_price" min="0" step="0.01" value="<?= e($maxPrice??'') ?>" placeholder="₺"></label><button type="submit">Uygula</button><a href="<?= e(url('category/'.rawurlencode($category['slug']))) ?>">Temizle</a></form><section><div class="products"><?php foreach($products as $p): ?><article class="product"><a class="product-link" href="<?= e(url('product/'.rawurlencode($p['slug']))) ?>"><div class="product-image"><?php if($p['image']): ?><img src="<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"><?php else: ?><span>GAME</span><?php endif; ?></div><h3><?= e($p['name']) ?></h3><p><?= e($p['short_description']) ?></p><strong><?= number_format((float)$p['price'],2,',','.') ?> ₺</strong></a></article><?php endforeach; ?><?php if(!$products): ?><div class="empty">Bu kategoride henüz yayında ürün bulunmuyor.</div><?php endif; ?></div></section>